};

export const Controlled: Story = {
  args: {
    design: nakaginDesign,
    kit: minimalKit,
    title: "Controlled",
  },
  render: (args) => {
    const [selection, setSelection] = React.useState({ pieceGuids: [firstPieceGuid] });
    return frame(<Model {...args} selection={selection} onSelectionChange={setSelection} />);
  },
};

